// İkili sayaç: butona her basışta sayı 1 artar, 4 LED sayıyı ikili gösterir.
const int LEDLER[] = {11, 10, 9, 8};  // soldan sağa: 8'ler, 4'ler, 2'ler, 1'ler basamağı
const int BUTON_PIN = 2;             // butonun öbür ucu GND'de; iç pull-up açık
const int EN_BUYUK = 15;             // 4 LED en çok 15 gösterir
const unsigned long TITRESIM_MS = 50;  // buton sıçramasını yok sayma süresi

int sayi = 0;
int oncekiOkuma = HIGH;
unsigned long sonDegisim = 0;

// Sayının her bitini kendi LED'ine yazar, seri ekrana da basar.
void goster(int n) {
  Serial.print("Sayi: ");
  Serial.print(n);
  Serial.print("  Ikili: ");
  for (int i = 0; i < 4; i++) {
    int bit = (n >> (3 - i)) & 1;  // soldaki LED en büyük basamak
    digitalWrite(LEDLER[i], bit ? HIGH : LOW);
    Serial.print(bit);
  }
  Serial.println();
}

void setup() {
  Serial.begin(9600);
  pinMode(BUTON_PIN, INPUT_PULLUP);
  for (int i = 0; i < 4; i++) {
    pinMode(LEDLER[i], OUTPUT);
  }
  goster(sayi);
}

void loop() {
  int okuma = digitalRead(BUTON_PIN);
  if (okuma != oncekiOkuma && millis() - sonDegisim > TITRESIM_MS) {
    sonDegisim = millis();
    if (okuma == LOW) {                    // basıldı
      sayi = (sayi + 1) % (EN_BUYUK + 1);  // 15'ten sonra 0
      goster(sayi);
    }
    oncekiOkuma = okuma;
  }
}
